/** Material de estudio editorial DIAN; los casos son inventados y no describen trámites reales. */
export type StudyCase = { context: string; question: string; answer: string; reasoning: string; mistake: string }
export type LawGuide = { essentials: string[]; workflow: string[]; cases: StudyCase; connections: string[]; reference: string }
export const dianLawGuides: Record<string, LawGuide> = {
  estatuto: {
    essentials: [
      'No es una sola regla: separa el nacimiento y determinación del tributo de su recaudo, devolución, cobro y discusión.',
      'En cartera diferencia obligación, declaración, vencimiento, título ejecutivo, exigibilidad y prescripción; son hechos jurídicos distintos.',
      'Los arts. 814, 817–818, 823 y siguientes, 828, 831 y 850 y siguientes sirven como mapa de lectura inicial, no como temario exhaustivo.'
    ], workflow:['Ubica tributo, concepto, período y sujeto obligado.','Reconstruye fechas, declaración, pagos, correcciones y actos.','Verifica la regla especial aplicable: cuenta, devolución, facilidad o cobro.','Identifica la autoridad competente, pruebas y garantías antes de proponer una decisión.'],
    cases:{context:'Una sociedad reporta un pago que el estado de cuenta no refleja. El sistema muestra saldo vencido.',question:'¿Debe prepararse de inmediato un mandamiento de pago?',answer:'No. Primero se verifica el recibo, el período, la imputación y la existencia de un título exigible.',reasoning:'El registro informático es un indicio para revisar, pero no sustituye el análisis de pagos ni los requisitos legales del cobro.',mistake:'Confundir saldo mostrado con deuda definitivamente depurada y jurídicamente exigible.'},connections:['decreto1625','ley1066','cpaca'],reference:'Estatuto Tributario: arts. 814, 817, 818, 823, 828, 831 y 850 y siguientes.'
  },
  cpaca:{essentials:['Ordena el actuar de las autoridades bajo debido proceso, publicidad, imparcialidad, eficacia y coordinación.','La notificación comunica un acto; la firmeza depende de condiciones posteriores. No son sinónimos.','Ante trámites tributarios especiales, verifica primero el Estatuto Tributario antes de usar una regla general del CPACA.'],workflow:['Identifica la petición o actuación y la autoridad competente.','Comprueba procedimiento especial y garantías.','Define acto, motivación, notificación y recursos aplicables.','Documenta la respuesta y su trazabilidad.'],cases:{context:'Una solicitud llega a una dependencia sin competencia y contiene datos suficientes para identificar al destinatario.',question:'¿Se archiva o se orienta el traslado conforme a la regla aplicable?',answer:'Se gestiona conforme a la regulación de competencia y traslado de peticiones, sin trasladar injustificadamente la carga al ciudadano.',reasoning:'El acceso efectivo a la administración y la coordinación son obligaciones de las autoridades.',mistake:'Tratar la falta de competencia propia como una excusa para abandonar la solicitud.'},connections:['ley1755','ley1712','estatuto'],reference:'Ley 1437/2011; distinguir procedimiento general de reglas tributarias especiales.'},
  decreto1625:{essentials:['Compila disposiciones reglamentarias tributarias; facilita localizar requisitos operativos concretos.','No reemplaza al Estatuto Tributario: una norma reglamentaria desarrolla la ley dentro de sus límites.','La compilación tiene modificaciones; se debe consultar artículo y fecha correspondiente, no memorizar un PDF estático.'],workflow:['Ubica trámite tributario y norma legal habilitante.','Busca el capítulo reglamentario específico.','Verifica soporte, sujeto, oportunidad y medio de presentación.','Comprueba modificaciones y requisitos particulares.'],cases:{context:'Un contribuyente solicita devolución y acredita un saldo en su declaración.',question:'¿Es suficiente la cifra declarada?',answer:'No: deben revisarse requisitos documentales, legitimación, oportunidad y reglas de la devolución.',reasoning:'La procedencia requiere contraste con el Estatuto Tributario y su desarrollo reglamentario.',mistake:'Asumir que saldo a favor equivale a pago inmediato.'},connections:['estatuto','ley1581'],reference:'Decreto 1625/2016; disposiciones reglamentarias propias del trámite.'},
  ley1066:{essentials:['Contiene disposiciones generales de normalización de cartera pública.','No homogeneiza automáticamente los procedimientos de cobro de todas las entidades.','En la DIAN debe examinarse la normativa tributaria especial, la competencia y el reglamento aplicable.'],workflow:['Identifica entidad y naturaleza del crédito.','Determina si aplica régimen general o especial.','Establece quién está facultado para gestionar y decidir.','Documenta trazabilidad de actuaciones y acuerdos.'],cases:{context:'Un servidor copia un formato de cobro de otra entidad estatal para usarlo en una obligación tributaria nacional.',question:'¿Es una buena práctica?',answer:'No sin antes verificar el procedimiento especial, acto de competencia y requisitos de la DIAN.',reasoning:'La normalización de cartera es objetivo común, pero el procedimiento aplicable depende de la naturaleza del crédito.',mistake:'Reproducir plazos y formatos ajenos sin sustento.'},connections:['estatuto','decreto1742'],reference:'Ley 1066/2006 y regímenes especiales de recaudo y cobro.'},
  ley1116:{essentials:['La reorganización busca preservar la empresa viable; la liquidación judicial tiene objetivo diferente.','La apertura de la reorganización tiene consecuencias sobre acciones de ejecución y cobro individuales según la ley.','La DIAN es acreedora y debe intervenir en el trámite colectivo, con soporte del crédito y atención a las reglas de prelación.'],workflow:['Verifica providencia de apertura y fecha.','Depura el crédito y soporte documental.','Identifica efectos sobre actuaciones de cobro y coordinación con el expediente concursal.','Presenta o sigue el crédito y controla decisiones y pagos conforme al proceso.'],cases:{context:'Una empresa tiene mandamiento de pago previo y luego ingresa a reorganización judicial.',question:'¿Se continúa de forma automática la ejecución individual?',answer:'No: primero se verifican los efectos del proceso de reorganización y el tratamiento del crédito.',reasoning:'La insolvencia introduce un procedimiento colectivo que puede modificar la ruta de actuaciones individuales.',mistake:'Creer que la reorganización extingue la deuda o que el cobro sigue igual.'},connections:['estatuto','decreto1742'],reference:'Ley 1116/2006, especialmente arts. 1, 19, 24 y normas aplicables sobre créditos fiscales.'},
  ley2586:{essentials:['Se ocupa de infracciones, sanciones y decomiso de mercancías en materia aduanera; no redefine por sí sola el cobro tributario nacional.','Entró en el corte temporal de la GOA por su expedición el 19 de junio de 2026; esto no confirma su presencia en indicadores individuales.','El art. 112 regula transición: operaciones iniciadas antes deben revisarse con su norma de origen y la favorabilidad pertinente.'],workflow:['Determina si el hecho es aduanero o tributario.','Ubica fecha de operación y etapa administrativa.','Estudia tipicidad, competencia y régimen transitorio.','Compara disposiciones vigentes y favorabilidad cuando sea pertinente.'],cases:{context:'Una importación inició antes del 19 de junio de 2026, pero la autoridad decide después.',question:'¿Basta citar la Ley 2586 para sancionar?',answer:'No: debe verificarse el régimen transitorio del art. 112 y la favorabilidad aplicable.',reasoning:'La ley conserva reglas para operaciones y actuaciones iniciadas con anterioridad y exige análisis temporal.',mistake:'Aplicar retroactivamente toda la nueva ley sin examinar la situación.'},connections:['d920','decreto1742','goa'],reference:'Ley 2586/2026, arts. 1, 112 y 114; cotejar texto oficial.'},
  d920:{essentials:['Es antecedente del régimen sancionatorio aduanero, derogado en general por Ley 2586.','La derogatoria no borra automáticamente el análisis de actos o actuaciones iniciados bajo la norma anterior.','Se estudia para entender transición, no como fuente de reglas nuevas de cartera tributaria.'],workflow:['Determina fecha del hecho o inicio de operación.','Identifica ley vigente en ese momento.','Consulta art. 112 de Ley 2586 y favorabilidad.','Justifica la norma aplicable al caso.'],cases:{context:'Un expediente de decomiso lleva meses en curso antes de la Ley 2586.',question:'¿Se rehace todo el trámite porque cambió la ley?',answer:'No automáticamente: se revisan las reglas de transición, actuaciones y términos ya iniciados.',reasoning:'Los actos procedimentales pueden continuar bajo el régimen previsto en las disposiciones transitorias.',mistake:'Igualar derogatoria a nulidad de actuaciones previas.'},connections:['ley2586'],reference:'Decreto Ley 920/2023, contrastado con Ley 2586/2026 art. 112.'},
  decreto1742:{essentials:['Organiza la DIAN en niveles central, local y delegado.','La Dirección de Gestión de Impuestos dirige lineamientos de recaudo, cobro y devolución; las direcciones seccionales ejercen funciones dentro de su competencia.','Los grupos, divisiones y ámbitos de competencia se detallan además en resoluciones: el decreto solo no basta para asignar un expediente.'],workflow:['Clasifica asunto: tributario, aduanero, cambiario o corporativo.','Determina nivel institucional y dirección temática.','Comprueba división y competencia territorial mediante acto vigente.','Canaliza actuación y documenta traslado cuando corresponda.'],cases:{context:'Un caso de devolución llega a un área de fiscalización aduanera.',question:'¿Quién lo resuelve?',answer:'La dependencia que resulte competente según materia, territorio y normas de reparto, no la primera que lo reciba.',reasoning:'La estructura distingue competencias y coordinación entre dependencias.',mistake:'Suponer que una dependencia central procesa todos los expedientes locales.'},connections:['res067','ficha','estatuto'],reference:'Decreto 1742/2020 arts. 4–7, 13 y 70; resoluciones de competencia en portal DIAN.'},
  res067:{essentials:['El MERF precisa funciones y requisitos por ficha de empleo.','Las competencias del empleo son el filtro principal para priorizar materiales, no la totalidad del quehacer de la DIAN.','La versión y modificaciones de la ficha deben corresponder a la OPEC inscrita.'],workflow:['Ubica denominación, código y grado.','Consulta ficha exacta y propósito.','Vincula cada función con conceptos de estudio.','Contrasta con indicadores publicados para ese empleo.'],cases:{context:'Un temario informal aconseja dedicar la mayoría del tiempo a un procedimiento aduanero.',question:'¿Qué se contrasta primero?',answer:'La ficha y los indicadores concretos del empleo.',reasoning:'La relevancia depende de las funciones y estructura de prueba asignada, no de rumores.',mistake:'Tratar la DIAN como un solo cargo genérico.'},connections:['ficha','goa','decreto1742'],reference:'Resolución DIAN 067/2024 y manual aplicable.'},
  ficha:{essentials:['CT-CR-3007 se utiliza en Umbral como referencia del empleo Gestor II.','Los ejes exactos de la prueba se deben contrastar con los indicadores individuales del operador.','El material transversal puede apoyar PJS sin ser un eje exclusivo de esa ficha.'],workflow:['Verifica OPEC, modalidad y ficha en SIMO.','Separa funciones principales de conocimientos transversales.','Conecta cada función con lecciones y casos.','Marca como no comprobada la cobertura de ejes no recibidos.'],cases:{context:'Umbral ofrece un bloque amplio de contratación estatal pero las funciones del empleo enfatizan cartera.',question:'¿Cómo se prioriza?',answer:'Primero los indicadores y funciones confirmadas; después material complementario.',reasoning:'La preparación debe responder al perfil seleccionado y no al catálogo completo de normas públicas.',mistake:'Afirmar cobertura oficial de un eje sin tener su denominación real.'},connections:['res067','goa','estatuto'],reference:'MERF DIAN, ficha CT-CR-3007 y OPEC individual.'},
  res065:{essentials:['Las competencias comportamentales describen atributos y disposiciones para el servicio.','No deben confundirse con pruebas funcionales de tres alternativas y una clave.','La GOA dispone autoinforme de cuatro grados de acuerdo para comportamentales e integridad.'],workflow:['Lee la afirmación sin buscar la “respuesta ideal”.','Identifica tu disposición habitual.','Elige grado de acuerdo que corresponda honestamente.','Distingue práctica pedagógica de medición psicométrica oficial.'],cases:{context:'Una afirmación dice que una persona adapta su explicación ante la dificultad de un usuario.',question:'¿Cuál es la respuesta “correcta”?',answer:'No hay clave correcta por afirmación; se responde con la propia disposición habitual.',reasoning:'La GOA define escala Likert sin respuestas correctas o incorrectas.',mistake:'Memorizar una escala de “valores deseables” como si fuera cuestionario de conocimientos.'},connections:['integridad','goa'],reference:'Resolución 065/2024 según documentación del curso; GOA 4.5 para formato de aplicación.'},
  integridad:{essentials:['La integridad conecta decisiones con honestidad, respeto, compromiso, diligencia y justicia según código institucional.','Ante un dilema se evalúa el comportamiento profesional coherente con el servicio y la legalidad.','El formato oficial es autoinforme, no un examen de “cuál valor suena mejor”.'],workflow:['Reconoce el dilema y los intereses involucrados.','Examina valores, competencia y protección de información.','En el autoinforme, responde cómo actúas habitualmente.','En casos formativos, discute por qué una decisión protege el interés general.'],cases:{context:'Un conocido solicita por mensaje informal los datos fiscales de otro contribuyente.',question:'¿Cuál sería una conducta íntegra en un caso de entrenamiento?',answer:'Negarse a divulgar información sin autorización y orientar los canales oficiales.',reasoning:'La confianza en la administración requiere reserva y trato igualitario.',mistake:'Confundir cercanía personal con autorización para entregar información.'},connections:['ley1581','ley1712','res065'],reference:'Código de Integridad DIAN y GOA 4.5; distinguir ejercicio de autoinforme.'},
  ley1755:{essentials:['Regula el derecho fundamental de petición y desarrolla modalidades, trámite y respuesta.','La respuesta debe ser oportuna, de fondo, clara y congruente; no equivale necesariamente a acceder a lo solicitado.','En materias con régimen especial pueden existir canales o disposiciones particulares.'],workflow:['Radica e identifica objeto y solicitante.','Verifica competencia y necesidad de traslado.','Determina el término aplicable a la clase de solicitud.','Da respuesta motivada y deja constancia de comunicación.'],cases:{context:'Una persona pide el estado de una solicitud tributaria ya visible en la plataforma.',question:'¿Se le manda a esperar hasta la decisión final?',answer:'No; se le informa el estado verificable y el canal de seguimiento, respetando las reservas aplicables.',reasoning:'El acceso a la información del trámite no se limita a su decisión final.',mistake:'Creer que responder “está en trámite” siempre es suficiente.'},connections:['cpaca','ley1712','ley1581'],reference:'Ley 1755/2015; GOA ejemplo PJS nivel asistencial, pp. 16–17.'},
  ley1712:{essentials:['Establece transparencia y acceso a información pública, con excepciones y reservas legales.','Exige facilitar consulta de información disponible y evitar obstáculos innecesarios.','No implica publicar datos tributarios o personales sujetos a reserva.'],workflow:['Clasifica información solicitada.','Valora publicidad, reserva o clasificación con base normativa.','Entrega lo público por canal adecuado.','Motiva cualquier restricción y registra la atención.'],cases:{context:'Un ciudadano solicita estadísticas agregadas de recaudo y otro pide declaraciones de terceros.',question:'¿Se responden igual?',answer:'No: datos agregados públicos y declaraciones sometidas a reserva requieren análisis distinto.',reasoning:'Transparencia y protección de información coexisten, de manera que cada solicitud exige evaluar el tipo de datos y su régimen aplicable.',mistake:'Negar todo por cautela o divulgar todo invocando transparencia.'},connections:['ley1581','ley1755','estatuto'],reference:'Ley 1712/2014, principios y excepciones legales.'},
  ley1581:{essentials:['Exige finalidad, seguridad y tratamiento adecuado de datos personales, sin desconocer regímenes legales especiales.','Identidad y autorizaciones deben verificarse antes de compartir datos a terceros.','La reserva tributaria contiene reglas adicionales a las de protección general de datos.'],workflow:['Determina clase de dato y finalidad.','Verifica legitimación y canal de acceso.','Minimiza información y protege el medio de entrega.','Conserva trazabilidad del uso o comunicación.'],cases:{context:'Alguien por teléfono conoce el NIT y solicita detalle de obligaciones.',question:'¿Basta conocer el NIT?',answer:'No: se debe verificar legitimación y canal autorizado antes de compartir información protegida.',reasoning:'Identificar una cuenta no prueba representación ni autorización.',mistake:'Confundir dato identificador con prueba de titularidad.'},connections:['ley1712','ley594'],reference:'Ley 1581/2012 y reserva especial tributaria.'},
  ley594:{essentials:['La gestión documental organiza, conserva y permite recuperar los documentos de la administración.','Un expediente válido necesita integridad, autenticidad y secuencia de actuaciones.','La trazabilidad no consiste solo en guardar archivos, sino relacionarlos con su procedimiento.'],workflow:['Identifica expediente y serie documental.','Organiza soportes según procedimiento y tabla aplicable.','Registra fecha, autoría, notificaciones y actuaciones.','Garantiza consulta autorizada, custodia y conservación.'],cases:{context:'Una dependencia tiene la resolución, pero no constancia de notificación.',question:'¿Es suficiente el PDF del acto?',answer:'No para demostrar por sí solo cómo fue comunicado; se requiere revisar y completar soporte conforme al trámite.',reasoning:'La fecha y forma de notificación pueden definir términos y garantías.',mistake:'Usar la existencia del documento como prueba automática de todos sus efectos.'},connections:['cpaca','estatuto'],reference:'Ley 594/2000; tablas documentales y procedimientos DIAN.'},
  decreto1083:{essentials:['Compila reglas de función pública y gestión de talento humano.','El régimen específico de la DIAN puede tener preferencia sobre reglas generales en materias reguladas especialmente.','La gestión de desempeño requiere diagnóstico, planeación, ejecución y evaluación sustentados.'],workflow:['Define si el asunto es función pública general o especial DIAN.','Selecciona política o instrumento de gestión apropiado.','Diagnostica brechas con evidencia.','Formula, ejecuta y evalúa acciones.'],cases:{context:'Se quiere conocer la madurez de talento humano antes de fijar planes.',question:'¿Se empieza verificando ejecución del plan o con diagnóstico?',answer:'Con diagnóstico usando el instrumento que corresponda, antes de diseñar acciones.',reasoning:'La planeación necesita una línea base verificable para ser pertinente y no debe confundirse la cantidad de actividades ejecutadas con el estado de madurez de la gestión.',mistake:'Confundir reporte de cumplimiento de actividades con diagnóstico integral.'},connections:['mipg','res067'],reference:'Decreto 1083/2015; GOA ejemplo profesional de diagnóstico MIPG, pp. 13–14.'},
  mipg:{essentials:['Es un marco de articulación de políticas y dimensiones de gestión, no una única herramienta de talento humano.','La versión 6.1 de febrero de 2026 incluye siete dimensiones; evitar usar sin aclaración imágenes de otra versión.','La Matriz de Gestión Estratégica de Talento Humano es un instrumento diagnóstico que se aplica en su contexto.'],workflow:['Delimita necesidad institucional.','Selecciona dimensión y política correspondiente.','Usa evidencia e instrumento para diagnóstico.','Planea mejora y realiza seguimiento de resultados.'],cases:{context:'Una oficina tiene listas de asistencia a capacitaciones pero desconoce el nivel de madurez del talento humano.',question:'¿El conteo de asistentes equivale al diagnóstico?',answer:'No: requiere un instrumento de diagnóstico de la política para identificar madurez y brechas.',reasoning:'El registro de actividades muestra ejecución, no necesariamente desempeño institucional.',mistake:'Asumir que una actividad realizada significa política cumplida.'},connections:['decreto1083','goa'],reference:'Manual Operativo MIPG 6.1 (febrero 2026); GOA ejemplo profesional, pp. 13–14.'},
  acuerdo21:{essentials:['Acuerdo y Anexo son el marco regulador principal del proceso DIAN 2676; la GOA es orientadora.','La ponderación cambia según modalidad, exigencia de experiencia y categoría de vacante.','Funcionales tienen carácter eliminatorio y umbral oficial de 70,00.'],workflow:['Identifica modalidad de ingreso/ascenso.','Comprueba requisitos del empleo y cuadro aplicable.','Revisa pruebas, ponderaciones y reglas de exclusión.','Usa SIMO para citaciones y reclamaciones concretas.'],cases:{context:'Un aspirante a ingreso sin experiencia exigida ve una tabla con funcionales al 65%.',question:'¿Debe usar ese porcentaje automáticamente?',answer:'No. Debe identificar en la GOA la tabla de su modalidad y requisito de experiencia.',reasoning:'Existen cuadros diferentes; para ingreso sin experiencia exigida la guía indica funcionales 70%.',mistake:'Usar ponderaciones de otro grupo de aspirantes.'},connections:['goa','ficha'],reference:'Acuerdo CNSC 21/2025 y Anexo; GOA pp. 9–11.'},
  goa:{essentials:['Funcionales: PJS de un caso, un enunciado y tres opciones, con una respuesta válida.','Comportamentales e integridad: cuatro grados de acuerdo, sin clave correcta por ítem.','Corte: normas vigentes expedidas hasta el 19/06/2026. Jornada prevista 08/11/2026, cinco horas, con condiciones particulares en SIMO.'],workflow:['Comprueba corte normativo e indicadores de tu empleo.','Entrena funcionales en formato PJS de tres opciones.','Responde autoinformes sin intentar calcular claves correctas.','Practica logística: citación, identidad, lápiz No. 2 y manejo de hoja óptica.'],cases:{context:'Umbral informa 83% de aciertos en un simulacro propio.',question:'¿Se puede afirmar que será la nota CNSC?',answer:'No: es porcentaje formativo; la GOA describe calificación con criterios psicométricos y análisis de ítems.',reasoning:'La calificación oficial no se obtiene directamente de un simulacro privado.',mistake:'Convertir porcentajes de práctica en probabilidad de aprobación.'},connections:['acuerdo21','ficha','ley2586'],reference:'GOA DIAN 2676 19/10/2026, §§ 4.2–4.7 y 5.'},
}

